let shopSettings=null;
const toolsRow=document.createElement('section');toolsRow.className='owner-tools';toolsRow.innerHTML='<button class="portal-button" id="shopsettings">◷ Store hours & pause orders</button><button class="portal-button" id="orderalerts">♧ Enable order notifications</button><button class="portal-button" id="bulkcatalog">▦ Bulk price & stock update</button><button class="portal-button" id="lowstock">Low stock</button>';$('#portalworkspace').prepend(toolsRow);
window.WK.receiveStore=s=>shopSettings=s;
const stockNotice=document.createElement('div');stockNotice.className='stock-alert';stockNotice.setAttribute('role','status');stockNotice.hidden=true;toolsRow.after(stockNotice);let knownLowStock=null;
const toolsProducts=window.WK.receiveProducts;window.WK.receiveProducts=function(list){toolsProducts(list);const low=list.filter(p=>p.stock<10),ids=new Set(low.map(p=>p.id));stockNotice.hidden=!low.length;stockNotice.textContent=low.length+' products are low on stock. Review Low stock before accepting more orders.';$('#lowstock').textContent='Low stock · '+low.length;if(allowed()&&knownLowStock&&low.some(p=>!knownLowStock.has(p.id)))notify('New low-stock alert. Review your inventory.');knownLowStock=ids};
$('#shopsettings').onclick=()=>{if(!allowed())return;const s=shopSettings||{paused:false,openMinute:420,closeMinute:1320,pickupAddress:window.WC_STORE_ADDRESS,pauseMessage:''},fmt=n=>(Math.floor(n/60)%24).toString().padStart(2,'0')+':'+(n%60).toString().padStart(2,'0');showModal(`<h2>Your shop, your hours.</h2><form id="storesettings"><label class="consent"><input name="paused" type="checkbox" ${s.paused?'checked':''}> Pause new orders now</label><label>Message while paused<input name="pauseMessage" maxlength="160" value="${escape(s.pauseMessage)}" placeholder="We’re catching up. Back soon."></label><label>Opens daily (India time)<input name="open" required type="time" value="${fmt(s.openMinute)}"></label><label>Closes daily (00:00 means midnight)<input name="close" required type="time" value="${fmt(s.closeMinute)}"></label><label>Exact pickup address<textarea name="pickupAddress" required minlength="10" maxlength="300">${escape(s.pickupAddress)}</textarea></label><label>Public store contact (+91)<input name="contactPhone" type="tel" maxlength="13" placeholder="+91 mobile number" value="${escape(s.contactPhone||'')}"></label><p class="form-note">Pausing stops new orders; existing orders still need to be fulfilled. Hours use India time and must open and close on the same day.</p><button class="primary wide">Save shop settings</button></form>`);$('#storesettings').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),minute=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]),button=e.target.querySelector('button');button.disabled=true;try{const clean={paused:data.paused==='on',contactPhone:data.contactPhone,pauseMessage:data.pauseMessage,openMinute:minute(data.open),closeMinute:minute(data.close)||1440,pickupAddress:data.pickupAddress};await window.WKCloud.saveStoreSettings(clean);shopSettings=clean;$('#modal').close();notify('Store hours and availability updated')}catch(err){notify(err.message);button.disabled=false}}};
$('#orderalerts').onclick=async e=>{if(!allowed())return;const button=e.target;button.disabled=true;try{await window.WKCloud.enableOrderAlerts();button.textContent='Order notifications enabled ✓';notify('Order alerts enabled on this device.')}catch(err){notify(err.message)}finally{button.disabled=false}};
$('#lowstock').onclick=()=>{if(!allowed())return;const low=products.filter(p=>p.stock<10);showModal(`<h2>Keep the essentials ready.</h2><p class="form-note">${low.length} products have fewer than ten units.</p>${low.map(p=>`<div class="revision-row"><b>${escape(p.name)}</b><span>${p.stock} left</span></div>`).join('')||'<p>All products have at least ten units.</p>'}<button class="primary wide" id="restock">Open inventory</button>`);$('#restock').onclick=()=>{$('#modal').close();showTab('inventory')}};
$('#bulkcatalog').onclick=()=>{if(!allowed())return;showModal('<h2>A quicker shelf update.</h2><p class="form-note">Download the current CSV, edit price or stock in a spreadsheet, then paste it below. Keep IDs and revisions unchanged. Up to 100 products per save; a conflicting edit stops the whole batch.</p><button class="portal-button" id="exportcatalog">Download catalog CSV</button><form id="bulkform"><label>CSV: id,price,stock,revision<textarea name="csv" class="bulk-area" required placeholder="id,price,stock,revision"></textarea></label><button class="primary wide">Review bulk changes</button></form>');$('#exportcatalog').onclick=()=>{const text='id,price,stock,revision\n'+products.map(p=>[p.id,p.price,p.stock,p.revision||0].join(',')).join('\n'),url=URL.createObjectURL(new Blob([text],{type:'text/csv'})),link=document.createElement('a');link.href=url;link.download='wakad-circle-catalog.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#bulkform').onsubmit=e=>{e.preventDefault();try{const batch=WCNext.catalogCSV(new FormData(e.target).get('csv'),products);showModal(`<h2>Review ${batch.length} changes</h2>${batch.map(p=>`<div class="revision-row"><span>${escape(p.name)}</span><b>${money(p.price)} · ${p.stock} units</b></div>`).join('')}<button class="primary wide" id="applybulk">Apply all changes</button>`);$('#applybulk').onclick=async event=>{event.target.disabled=true;try{await window.WKCloud.bulkSaveProducts(batch);$('#modal').close();notify('Catalog updated across connected apps.')}catch(err){notify(err.message);event.target.disabled=false}}}catch(err){notify(err.message)}}};
